", "spacefractions/repository.py": """"SQLite persistence layer (QuestionComponent + persistence).

The schema mirrors the architecture's SQL DDL intent:
    CREATE TABLE games (id ..., game_state ...);
with JSON persisted as the game state (JSONB in Postgres, TEXT/JSON here).
"""

from __future__ import annotations

import json
import os
import sqlite3
from typing import List, Optional

from .models import Game, Question


DEFAULT_DB_PATH = os.path.join(
    os.path.expanduser("~"), ".spacefractions", "spacefractions.db"
)


_SCHEMA = """
CREATE TABLE IF NOT EXISTS questions (
    id TEXT PRIMARY KEY,
    prompt TEXT NOT NULL,
    options TEXT NOT NULL,   -- JSON list of strings
    correct_index INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS games (
    id TEXT PRIMARY KEY,
    game_state TEXT NOT NULL  -- JSON object
);

CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    username TEXT NOT NULL UNIQUE,
    role TEXT NOT NULL,          -- 'user' or 'admin'
    salt TEXT NOT NULL,
    password_hash TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS score_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL,
    game_id TEXT NOT NULL,
    score INTEGER NOT NULL,
    total INTEGER NOT NULL,
    played_at TEXT NOT NULL
);
"""

_SEED_QUESTIONS = [
    ("What is 1/2 + 1/4 ?", ["3/4", "2/6", "1/2", "1"], 0),
    ("What is 3/4 - 1/4 ?", ["1/2", "2/4", "1", "1/4"], 0),
    ("What is 1/3 + 1/3 ?", ["2/3", "1/6", "2/6", "1/3"], 0),
    ("What is 1/2 * 1/2 ?", ["1/4", "1", "1/2", "2/4"], 0),
    ("What is 2/3 - 1/6 ?", ["1/2", "1/3", "1/6", "3/6"], 0),
    ("What is 3/4 + 1/2 ?", ["5/4", "1", "4/6", "3/8"], 0),
    ("What fraction equals 0.5 ?", ["1/2", "1/3", "1/4", "2/5"], 0),
    ("What is 5/6 - 1/3 ?", ["1/2", "2/3", "1/3", "4/6"], 0),
    ("What is 1/5 + 2/5 ?", ["3/5", "3/10", "2/5", "1"], 0),
    ("What is 2/3 * 3/4 ?", ["1/2", "6/7", "5/12", "2/4"], 0),
]


class Database:
    """Thin connection helper wrapping the sqlite3 module."""

    def __init__(self, db_path: Optional[str] = None):
        self.db_path = db_path or DEFAULT_DB_PATH
        os.makedirs(os.path.dirname(self.db_path), exist_ok=True)
        self._conn = sqlite3.connect(self.db_path)
        self._conn.row_factory = sqlite3.Row

    def conn(self) -> sqlite3.Connection:
        return self._conn

    def close(self) -> None:
        self._conn.close()

    def initialize(self) -> None:
        with self._conn:
            self._conn.executescript(_SCHEMA)

    def __enter__(self) -> "Database":
        return self

    def __exit__(self, *exc) -> None:
        self.close()


class QuestionRepository:
    """CRUD for the question bank."""

    def __init__(self, db: Database):
        self._db = db

    def seed(self) -> None:
        """Insert default questions if the bank is empty."""
        if self.count() == 0:
            for prompt, options, correct_index in _SEED_QUESTIONS:
                self.add(Question(prompt, options, correct_index))

    def all(self) -> List[Question]:
        cur = self._db.conn().execute(
            "SELECT id, prompt, options, correct_index FROM questions ORDER BY rowid"
        )
        rows = cur.fetchall()
        return [
            Question(
                prompt=r["prompt"],
                options=json.loads(r["options"]),
                correct_index=r["correct_index"],
                id=r["id"],
            )
            for r in rows
        ]

    def get(self, question_id: str) -> Optional[Question]:
        cur = self._db.conn().execute(
            "SELECT id, prompt, options, correct_index FROM questions WHERE id = ?",
            (question_id,),
        )
        r = cur.fetchone()
        if r is None:
            return None
        return Question(
            prompt=r["prompt"],
            options=json.loads(r["options"]),
            correct_index=r["correct_index"],
            id=r["id"],
        )

    def add(self, question: Question) -> None:
        with self._db.conn():
            self._db.conn().execute(
                "INSERT INTO questions (id, prompt, options, correct_index) "
                "VALUES (?, ?, ?, ?)",
                (
                    question.id,
                    question.prompt,
                    json.dumps(question.options),
                    question.correct_index,
                ),
            )

    def update(self, question: Question) -> None:
        with self._db.conn():
            self._db.conn().execute(
                "UPDATE questions SET prompt = ?, options = ?, correct_index = ? "
                "WHERE id = ?",
                (
                    question.prompt,
                    json.dumps(question.options),
                    question.correct_index,
                    question.id,
                ),
            )

    def delete(self, question_id: str) -> None:
        with self._db.conn():
            self._db.conn().execute(
                "DELETE FROM questions WHERE id = ?", (question_id,)
            )

    def count(self) -> int:
        cur = self._db.conn().execute("SELECT COUNT(*) AS c FROM questions")
        return cur.fetchone()["c"]


class GameRepository:
    """Persist games (game_state JSON) and score history."""

    def __init__(self, db: Database):
        self._db = db

    def save(self, game: Game) -> None:
        state = {
            "id": game.id,
            "score": game.score,
            "current_index": game.current_index,
            "answers": game._answers,
            "question_ids": [q.id for q in game.questions],
        }
        with self._db.conn():
            self._db.conn().execute(
                "INSERT OR REPLACE INTO games (id, game_state) VALUES (?, ?)",
                (game.id, json.dumps(state)),
            )

    def load(self, game_id: str, questions: List[Question]) -> Optional[Game]:
        cur = self._db.conn().execute(
            "SELECT game_state FROM games WHERE id = ?", (game_id,)
        )
        r = cur.fetchone()
        if r is None:
            return None
        state = json.loads(r["game_state"])
        by_id = {q.id: q for q in questions}
        qs = [by_id[qid] for qid in state.get("question_ids", []) if qid in by_id]
        game = Game(
            questions=qs,
            score=state.get("score", 0),
            id=state.get("id", game_id),
        )
        game.current_index = state.get("current_index", 0)
        game._answers = state.get("answers", [])
        return game

    def record_score(
        self, username: str, game_id: str, score: int, total: int
    ) -> None:
        import datetime

        with self._db.conn():
            self._db.conn().execute(
                "INSERT INTO score_history "
                "(username, game_id, score, total, played_at) VALUES (?, ?, ?, ?, ?)",
                (
                    username,
                    game_id,
                    score,
                    total,
                    datetime.datetime.now().isoformat(timespec="seconds"),
                ),
            )

    def history(self, username: Optional[str] = None) -> List[dict]:
        if username:
            cur = self._db.conn().execute(
                "SELECT * FROM score_history WHERE username = ? ORDER BY id DESC",
                (username,),
            )
        else:
            cur = self._db.conn().execute(
                "SELECT * FROM score_history ORDER BY id DESC"
            )
        return [dict(r) for r in cur.fetchall()]
", "spacefractions/auth.py": """"UserComponent: local authentication and authorization.

Passwords are salted and hashed with hashlib (PBKDF2-HMAC-SHA256).
Roles: 'user' (end user) and 'admin' (administrator).
"""

from __future__ import annotations

import hashlib
import secrets
from typing import Optional

from .models import Admin, User
from .repository import Database

_ITERATIONS = 100_000


def _hash_password(password: str, salt: str) -> str:
    dk = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt.encode("utf-8"), _ITERATIONS
    )
    return dk.hex()


class AuthService:
    """Manages users and validates credentials."""

    def __init__(self, db: Database):
        self._db = db

    def register(
        self, username: str, password: str, role: str = "user"
    ) -> Optional[User]:
        """Create a new account. Returns the User or None if taken."""
        username = username.strip()
        if not username or not password:
            return None
        salt = secrets.token_hex(16)
        phash = _hash_password(password, salt)
        user_id = (User(username).id if role == "user" else Admin(username).id)
        try:
            with self._db.conn():
                self._db.conn().execute(
                    "INSERT INTO users (id, username, role, salt, password_hash) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (user_id, username, role, salt, phash),
                )
        except Exception:
            return None
        if role == "admin":
            return Admin(username=username, id=user_id)
        return User(username=username, id=user_id)

    def authenticate(
        self, username: str, password: str
    ) -> Optional[dict]:
        """Validate credentials; returns {id, username, role} or None."""
        cur = self._db.conn().execute(
            "SELECT id, username, role, salt, password_hash FROM users "
            "WHERE username = ?",
            (username,),
        )
        r = cur.fetchone()
        if r is None:
            return None
        expected = _hash_password(password, r["salt"])
        if not secrets.compare_digest(expected, r["password_hash"]):
            return None
        return {"id": r["id"], "username": r["username"], "role": r["role"]}

    def exists(self, username: str) -> bool:
        cur = self._db.conn().execute(
            "SELECT 1 FROM users WHERE username = ?", (username,)
        )
        return cur.fetchone() is not None

    def ensure_admin(self, username: str = "admin", password: str = "admin123") -> None:
        """Ensure a default admin account exists (for first run)."""
        if not self.exists(username):
            self.register(username, password, role="admin")
", "spacefractions/service.py": """"GameComponent: game orchestration and the state machine.

States: Playing, Paused, GameOver.
Transitions:
    [*]      -> Playing   (start)
    Playing  -> Paused    pause()
    Paused   -> Playing   resume()
    Playing  -> GameOver  gameOver()
"""

from __future__ import annotations

import random
from enum import Enum
from fractions import Fraction
from typing import List, Optional

from .models import Game, Question


class GameState(str, Enum):
    PLAYING = "Playing"
    PAUSED = "Paused"
    GAME_OVER = "GameOver"


class FractionGenerator:
    """Generate random fraction questions with exact Fraction arithmetic."""

    _OPERATIONS = [("+", lambda a, b: a + b), ("-", lambda a, b: a - b)]

    @staticmethod
    def _render(f: Fraction) -> str:
        if f.denominator == 1:
            return str(f.numerator)
        return f"{f.numerator}/{f.denominator}"

    @classmethod
    def generate(cls, rng: Optional[random.Random] = None) -> Question:
        """Build one question with 4 options (exact, unique)."""
        rng = rng or random
        op_text, op = rng.choice(cls._OPERATIONS)
        d1 = rng.randint(2, 6)
        d2 = rng.randint(2, 6)
        n1 = rng.randint(1, d1 - 1)
        n2 = rng.randint(1, d2 - 1)
        a = Fraction(n1, d1)
        b = Fraction(n2, d2)
        correct = op(a, b)
        prompt = f"What is {cls._render(a)} {op_text} {cls._render(b)} ?"

        # Build distractors near the correct value.
        options = {cls._render(correct)}
        while len(options) < 4:
            candidate = correct + Fraction(rng.randint(-3, 3), rng.randint(2, 5))
            if candidate <= 0:
                candidate = correct + Fraction(1, rng.randint(2, 5))
            options.add(cls._render(candidate))
        ordered = list(options)
        rng.shuffle(ordered)
        correct_index = ordered.index(cls._render(correct))
        return Question(prompt=prompt, options=ordered, correct_index=correct_index)


class GameService:
    """Runs a game session: state, scoring, and answer checking."""

    def __init__(
        self,
        questions: List[Question],
        username: str = "guest",
        generator: Optional[FractionGenerator] = None,
        num_questions: int = 6,
    ):
        self._username = username
        self.generator = generator or FractionGenerator()
        self.state: GameState = GameState.PLAYING
        self.game = Game(
            questions=self._pick_questions(questions, num_questions)
        )
        self.game.play()

    def _pick_questions(
        self, questions: List[Question], num_questions: int
    ) -> List[Question]:
        """Choose up to num_questions from the bank; top up with generated ones."""
        bank = list(questions)
        random.shuffle(bank)
        chosen = bank[:num_questions]
        while len(chosen) < num_questions:
            chosen.append(self.generator.generate())
        return chosen

    @property
    def currentQuestion(self) -> Optional[Question]:
        return self.game.currentQuestion()

    def submitAnswer(self, answer: str) -> bool:
        """Submit an answer; return True if correct."""
        if self.state != GameState.PLAYING:
            return False
        correct = self.game.submit(answer)
        if self.game.is_over:
            self.state = GameState.GAME_OVER
        return correct

    def pause(self) -> None:
        if self.state == GameState.PLAYING:
            self.state = GameState.PAUSED

    def resume(self) -> None:
        if self.state == GameState.PAUSED:
            self.state = GameState.PLAYING

    def gameOver(self) -> None:
        self.state = GameState.GAME_OVER

    def viewScore(self) -> int:
        return self.game.viewScore()

    def totalQuestions(self) -> int:
        return len(self.game.questions)

    @property
    def is_over(self) -> bool:
        return self.state == GameState.GAME_OVER or self.game.is_over
", "spacefractions/ui.py": """"Tkinter user interface for Space Fractions.

Views:
    IntroMovieView  — animated space-themed introduction (skippable)
    MainMenuView    — Play / View Score / Help / Admin / Quit
    GameView        — series of fraction questions
    EndingView      — ending scene with score & feedback
    AdminView       — manage the question bank (admin only)

The UI layer is intentionally thin: all logic lives in service/repository.
"""

from __future__ import annotations

import tkinter as tk
from tkinter import messagebox, simpledialog, ttk
from typing import Callable, Optional

from .repository import GameRepository, QuestionRepository
from .service import GameService, GameState


class App(tk.Tk):
    """Top-level application window."""

    def __init__(self, db, repository, auth):
        super().__init__()
        self.db = db
        self.question_repo: QuestionRepository = repository
        self.auth = auth
        self.title("Space Fractions")
        self.geometry("900x600")
        self.minsize(720, 480)
        self._user: Optional[dict] = None
        self._frame: Optional[tk.Frame] = None
        self.show_intro()

    def _swap(self, frame: tk.Frame) -> None:
        if self._frame is not None:
            self._frame.destroy()
        self._frame = frame
        frame.pack(fill="both", expand=True)

    def show_intro(self) -> None:
        self._swap(IntroMovieView(self, on_done=self.show_menu))

    def show_menu(self) -> None:
        self._swap(
            MainMenuView(
                self,
                username=(self._user or {}).get("username"),
                on_play=self.start_game,
                on_score=self.show_scores,
                on_help=self.show_help,
                on_admin=self.show_admin,
                on_admin_login=self.admin_login,
                on_quit=self.destroy,
            )
        )

    def start_game(self) -> None:
        questions = self.question_repo.all()
        service = GameService(
            questions, username=(self._user or {}).get("username", "guest")
        )
        self._game_service = service
        self._swap(GameView(self, service, on_done=self.finish_game))

    def finish_game(self, service: GameService) -> None:
        GameRepository(self.db).record_score(
            (self._user or {}).get("username", "guest"),
            service.game.id,
            service.viewScore(),
            service.totalQuestions(),
        )
        self._swap(
            EndingView(
                self, service, on_menu=self.show_menu, on_replay=self.start_game
            )
        )

    def show_scores(self) -> None:
        history = GameRepository(self.db).history(
            (self._user or {}).get("username")
            if self._user
            else None
        )
        self._swap(ScoreView(self, history, on_back=self.show_menu))

    def show_help(self) -> None:
        self._swap(HelpView(self, on_back=self.show_menu))

    def show_admin(self) -> None:
        if not self._user or self._user.get("role") != "admin":
            messagebox.showinfo("Admin", "You must sign in as an admin first.")
            self.admin_login()
            return
        self._swap(AdminView(self, on_back=self.show_menu))

    def admin_login(self) -> None:
        username = simpledialog.askstring("Admin login", "Username:", parent=self)
        if username is None:
            return
        password = simpledialog.askstring(
            "Admin login", "Password:", show="*", parent=self
        )
        if password is None:
            return
        result = self.auth.authenticate(username, password)
        if result and result.get("role") == "admin":
            self._user = result
            messagebox.showinfo("Admin", "Signed in as admin.")
            self.show_admin()
        else:
            messagebox.showerror("Admin", "Invalid admin credentials.")


class IntroMovieView(tk.Frame):
    """Animated introduction; press any key or click to skip."""

    def __init__(self, master, on_done: Callable[[], None]):
        super().__init__(master, bg="#050510")
        self.on_done = on_done
        self._steps = 0
        self._canvas = tk.Canvas(self, bg="#050510", highlightthickness=0)
        self._canvas.pack(fill="both", expand=True)
        self._title = self._canvas.create_text(
            450, 200, text="SPACE FRACTIONS", fill="#7fd4ff",
            font=("Segoe UI", 40, "bold")
        )
        self._sub = self._canvas.create_text(
            450, 260, text="An adventure among the numbers",
            fill="#cceeff", font=("Segoe UI", 16)
        )
        self._ship = self._canvas.create_oval(
            420, 400, 480, 440, fill="#ffffff"
        )
        self._stars = [
            self._canvas.create_oval(x, y, x + 2, y + 2, fill="white")
            for x, y in self._random_stars()
        ]
        self._hint = self._canvas.create_text(
            450, 540, text="— press any key or click to continue —",
            fill="#8899aa", font=("Segoe UI", 12)
        )
        self.bind("<Button-1>", self._skip)
        self.bind("<Key>", self._skip)
        self.focus_set()
        self._animate()

    @staticmethod
    def _random_stars():
        import random

        return [(random.randint(0, 900), random.randint(0, 560)) for _ in range(60)]

    def _animate(self):
        if not self.winfo_exists():
            return
        self._steps += 1
        self._canvas.move(self._ship, 0, -2 if self._steps % 4 == 0 else 0)
        color = "#7fd4ff" if self._steps % 20 < 10 else "#ffffff"
        self._canvas.itemconfig(self._title, fill=color)
        self._after = self.after(30, self._animate)

    def _skip(self, _event=None):
        if hasattr(self, "_after"):
            self.after_cancel(self._after)
        self.on_done()


